"""Rendering the generated reference (plan/pipelines.md §7.2 render; plan/site.md, "Generated reference"): the dumps and
the parsed tables of one pin become src/generated/reference/<table>.md and values.json.

render_all(folder, pin, examples, layout) returns ({file name: text}, problems). Every table starts with its stamp:
<!-- generated by tools/reference.py render <c_Version>; engine <full pin>; sha256 <hex of the rest of the file>; do not
edit -->. Engine text goes through md() (escaped for Markdown and HTML) or code() (a code span); it is never raw HTML.
"""

import glob
import hashlib
import json
import os
import re

c_Version = '1'
c_StampPattern = re.compile(r'^<!-- generated by tools/reference\.py render (\S+); engine ([0-9a-f]{40}); sha256 ([0-9a-f]{64}); do not edit -->$')
# The page a table makes, estimated from its Markdown (pipelines.md §7.2: reference/commands, one page that includes a
# file per command group, must stay within the largest page's budget). Fitted by least squares to the fifteen built
# reference pages of the release book-v0.8.0-r2 that include generated files (2026-11-25, the markup after R59: the
# sidebar of 37.5 KB, code blocks without their foreground spans): 102 KB of the page's own markup with the prose a
# page writes around its tables, 1.46 bytes of HTML per byte of Markdown outside code fences (table cells, code spans)
# and 289 bytes per line of a fence. reference/commands builds to 1,547 KB and is estimated at 1,541; the other pages
# agree within 10 per cent but the two that write the most prose of their own (renderer, scene: 17 per cent under).
# The budget is the largest page of tools/budgets.json (bytes before compression).
c_PageChromeBytes = 102 * 1024
c_CodeLineBytes = 289
c_ProseFactor = 1.46
c_Presets = ('Low', 'Medium', 'High', 'Ultra')
c_DumpFiles = ('commands', 'preferences', 'templates', 'samples', 'settings', 'components', 'component-defaults')


class RenderError(Exception):
    """The dumps and parsed tables do not fit together: the message names the file and says what to do."""


# ---------------------------------------------------------------------------------------------------------------------
# Text.

def md(text):
    """Engine text as Markdown that shows it as written: HTML's special characters as entities, Markdown's as escapes,
    on one line."""
    if text is None:
        return ''
    text = ' '.join(str(text).split())
    text = text.replace('\\', '\\\\')
    text = text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;').replace('`', '&#96;')
    text = re.sub(r'([*_\[\]$~|])', r'\\\1', text)
    text = re.sub(r':(?=[A-Za-z])', r'\\:', text)  # never the start of a text directive (:name[…])
    return text


def code(text):
    """A code span of engine text (a name, a value, a type); a backtick inside widens the fence. In a table cell, row()
    escapes its pipes."""
    text = ' '.join(str(text).split())
    fence = '`'
    while fence in text:
        fence += '`'
    padded = ' %s ' % text if text.startswith('`') or text.endswith('`') else text
    return fence + padded + fence


def value_text(value):
    """A JSON value as a table shows it: a code span of its JSON (strings without quotes), or nothing for null."""
    if value is None:
        return ''
    if isinstance(value, str):
        return code(value) if value else code('""')
    return code(json.dumps(value, ensure_ascii=False, separators=(', ', ': ')))


def sentences(parts):
    """Pieces of a description joined as sentences: each ends with a full stop unless it ends with punctuation."""
    out = []
    for part in parts:
        part = part.strip()
        if part:
            out.append(part if part[-1] in '.!?' else part + '.')
    return ' '.join(out)


def cell_text(cell):
    """A table cell: a pipe inside a code span would end the cell, so it is escaped there (GFM reads \\| in a cell as |, also
    inside code); md() escapes the pipes of plain text already, and its text holds no backtick."""
    return re.sub(r'(`+)(.+?)\1', lambda found: found.group(1) + found.group(2).replace('|', '\\|') + found.group(1), cell)


def row(cells):
    return '| ' + ' | '.join(cell_text(cell) if cell else ' ' for cell in cells) + ' |'


def table(headers, rows):
    lines = [row(headers), row(['---'] * len(headers))]
    lines += [row(cells) for cells in rows]
    return '\n'.join(lines)


def details(summary, value):
    """A closed <details> with a JSON value in a json fence. The summary is raw HTML, where Markdown's backslash escapes
    are not read: it gets the HTML escapes only."""
    body = json.dumps(value, indent=2, ensure_ascii=False)
    fence = '```'
    while fence in body:
        fence += '`'
    return '<details>\n<summary>%s</summary>\n\n%sjson\n%s\n%s\n\n</details>' % (html_text(summary), fence, body, fence)


def html_text(text):
    """Text as HTML shows it: &, <, > and " as entities, on one line."""
    text = ' '.join(str(text).split())
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;')


def where(path, line=None):
    return code('%s:%d' % (path, line) if line else path)


def stamp(pin, body):
    digest = hashlib.sha256(body.encode('utf-8')).hexdigest()
    return '<!-- generated by tools/reference.py render %s; engine %s; sha256 %s; do not edit -->\n' % (c_Version, pin, digest)


def finish(pin, parts):
    body = '\n\n'.join(part.strip('\n') for part in parts if part) + '\n'
    return stamp(pin, body) + body


def read_stamp(text):
    """{version, engine, sha256, actual} of a generated file's first line, or None when it has no stamp."""
    first, _, rest = text.partition('\n')
    match = c_StampPattern.match(first)
    if not match:
        return None
    return {'version': match.group(1), 'engine': match.group(2), 'sha256': match.group(3),
            'actual': hashlib.sha256(rest.encode('utf-8')).hexdigest()}


def page_estimate(text):
    """The bytes of HTML a page that includes this Markdown is estimated to have (c_PageChromeBytes and the factors)."""
    code_lines = 0
    code_bytes = 0
    for match in re.finditer(r'^(`{3,})[^\n]*\n(.*?)\n\1$', text, flags=re.S | re.M):
        code_lines += match.group(2).count('\n') + 1
        code_bytes += len(match.group(0).encode('utf-8'))
    prose = len(text.encode('utf-8')) - code_bytes
    return int(c_PageChromeBytes + prose * c_ProseFactor + code_lines * c_CodeLineBytes)


def page_budget(budgets_path):
    """The largest page's budget in bytes (tools/budgets.json, largest_page_kilobytes)."""
    try:
        with open(budgets_path, encoding='utf-8') as file:
            kilobytes = json.load(file)['largest_page_kilobytes']
    except (OSError, ValueError, KeyError, TypeError) as error:
        raise RenderError('%s: no largest_page_kilobytes (%s): the commands table is split by the page budget it holds' % (
            os.path.basename(budgets_path), error))
    return int(kilobytes * 1024)


# ---------------------------------------------------------------------------------------------------------------------
# Inputs.

class Inputs:
    """The dumps and parsed tables of one pin, read once; dump() and route() raise RenderError naming what is missing."""

    def __init__(self, folder, pin):
        self.folder = folder
        self.pin = pin
        self.dumps = {}
        self.parsed = {}
        for name in c_DumpFiles:
            path = os.path.join(folder, name + '.json')
            if os.path.isfile(path):
                self.dumps[name] = self.load(path, name + '.json')
        parsed = os.path.join(folder, 'parsed')
        if os.path.isdir(parsed):
            for name in sorted(os.listdir(parsed)):
                if name.endswith('.json'):
                    self.parsed[name[:-5]] = self.load(os.path.join(parsed, name), 'parsed/' + name)

    def load(self, path, label):
        try:
            with open(path, encoding='utf-8') as file:
                data = json.load(file)
        except ValueError as error:
            raise RenderError('reference/_dumps/%s/%s: not valid JSON (%s): run python -I tools/reference.py dump and parse again'
                              % (self.pin, label, error))
        if not isinstance(data, dict) or data.get('pin') != self.pin:
            raise RenderError('reference/_dumps/%s/%s: made at another pin: run python -I tools/reference.py dump and parse at the pin'
                              % (self.pin, label))
        return data

    def dump(self, name):
        if name not in self.dumps:
            raise RenderError('reference/_dumps/%s/%s.json: missing: run python -I tools/reference.py dump --only %s at the pin'
                              % (self.pin, name, name))
        return self.dumps[name]['result']

    def route(self, name):
        if name not in self.parsed:
            raise RenderError('reference/_dumps/%s/parsed/%s.json: missing: run python -I tools/reference.py parse at the pin'
                              % (self.pin, name))
        return self.parsed[name]


# ---------------------------------------------------------------------------------------------------------------------
# Commands.

def schema_type(schema):
    kind = schema.get('type')
    if isinstance(kind, list):
        text = ' or '.join(kind)
    else:
        text = kind or ('one of several forms (see the schema)' if 'oneOf' in schema or 'anyOf' in schema else 'any')
    if kind == 'array' and isinstance(schema.get('items'), dict) and schema['items'].get('type'):
        items = schema['items']['type']
        text = 'array of %s' % (' or '.join(items) if isinstance(items, list) else items)
    return text


def schema_notes(schema):
    """The constraints of a parameter's schema, in words (enum, range, items, pattern)."""
    notes = []
    if 'enum' in schema:
        notes.append('One of: %s.' % ', '.join(value_text(value) for value in schema['enum']))
    items = schema.get('items') if isinstance(schema.get('items'), dict) else {}
    if 'enum' in items:
        notes.append('Items: one of %s.' % ', '.join(value_text(value) for value in items['enum']))
    bounds = []
    for key, word in (('minimum', 'at least'), ('exclusiveMinimum', 'more than'), ('maximum', 'at most'), ('exclusiveMaximum', 'less than')):
        if key in schema and not isinstance(schema[key], bool):
            bounds.append('%s %s' % (word, value_text(schema[key])))
    if bounds:
        notes.append('Value: %s.' % ', '.join(bounds))
    counts = []
    for key, word in (('minItems', 'at least'), ('maxItems', 'at most')):
        if key in schema:
            counts.append('%s %s' % (word, schema[key]))
    if counts:
        notes.append('Items: %s.' % ', '.join(counts))
    if schema.get('uniqueItems'):
        notes.append('Items are unique.')
    if 'pattern' in schema:
        notes.append('Pattern: %s.' % code(schema['pattern']))
    if schema.get('deprecated'):
        notes.append('Deprecated.')
    return ' '.join(notes)


def parameter_rows(schema, prefix=''):
    rows = []
    properties = schema.get('properties') if isinstance(schema.get('properties'), dict) else {}
    required = set(schema.get('required') or [])
    for name in sorted(properties):
        item = properties[name] if isinstance(properties[name], dict) else {}
        full = prefix + name
        description = md(item.get('description'))
        notes = schema_notes(item)
        rows.append([code(full), md(schema_type(item)), 'yes' if name in required else 'no', value_text(item.get('default')) if 'default' in item else '',
                     sentences([description, notes])])
        if isinstance(item.get('properties'), dict):
            rows += parameter_rows(item, full + '.')
        elif isinstance(item.get('items'), dict) and isinstance(item['items'].get('properties'), dict):
            rows += parameter_rows(item['items'], full + '[].')
    return rows


def toolsets_of(name, toolsets):
    """McpToolsets::GetToolsets: core when listed, then the exact name's toolset, else the first prefix's, else the group."""
    found = ['core'] if name in toolsets['core'] else []
    for exact, toolset in toolsets['exact']:
        if name == exact:
            found.append(toolset)
            return found
    for prefix, toolset in toolsets['prefixes']:
        if name.startswith(prefix):
            found.append(toolset)
            return found
    found.append(name.split('.', 1)[0])
    return found


def command_section(command, registration, toolsets, example, level='###'):
    name = command['name']
    lines = ['%s %s' % (level, name), md(command.get('description'))]
    facts = [
        'Kind: %s' % code(command.get('kind')),
        'Results: %s' % code(registration['results']),
        'MCP toolsets: %s' % ', '.join(code(item) for item in toolsets_of(name, toolsets)),
        'Answers later (MayDefer): %s' % ('yes' if registration['mayDefer'] else 'no'),
        'Waits for the asset scan: %s' % ('yes' if registration['waitsForAssets'] or command.get('kind') == 'Edit' else 'no'),
        'Registered at %s' % where(registration['file'], registration['line']),
    ]
    lines.append(' · '.join(facts))
    parameters = command.get('parameters') or {}
    rows = parameter_rows(parameters)
    if rows:
        lines.append(table(['Parameter', 'Type', 'Required', 'Default', 'Description'], rows))
    else:
        lines.append('No parameters.')
    lines.append(details('Parameter schema of %s' % name, parameters))
    if example is not None:
        lines.append(details('Example result of %s (recorded by a tutorial run)' % name, example))
    return '\n\n'.join(lines)


def read_examples(examples):
    """{command: result} of reference/_examples/<command>.json ({"pin", "command", "parameters", "result"})."""
    found = {}
    for path in sorted(glob.glob(os.path.join(examples, '*.json'))):
        try:
            with open(path, encoding='utf-8') as file:
                data = json.load(file)
        except ValueError as error:
            raise RenderError('reference/_examples/%s: not valid JSON (%s): run python -I tools/tutorials.py run --record-examples again'
                              % (os.path.basename(path), error))
        if not isinstance(data, dict) or 'command' not in data or 'result' not in data:
            raise RenderError('reference/_examples/%s: not {"pin", "command", "parameters", "result"}: record it with python -I '
                              'tools/tutorials.py run --record-examples' % os.path.basename(path))
        found[data['command']] = data['result']
    return found


def render_commands(inputs, examples, budget):
    commands = inputs.dump('commands').get('commands') or []
    parsed = inputs.route('commands')
    registrations = {record['name']: record for record in parsed['registrations']}
    missing = sorted(command['name'] for command in commands if command['name'] not in registrations)
    if missing:
        raise RenderError('reference/_dumps/%s/parsed/commands.json: no registration of %s, which editor.commands lists: run python -I '
                          'tools/reference.py parse, and change the commands route if it still misses them' % (inputs.pin, ', '.join(missing)))
    groups = {}
    for command in sorted(commands, key=lambda item: item['name']):
        groups.setdefault(command['name'].split('.', 1)[0], []).append(command)
    kinds = {}
    for command in commands:
        kinds[command.get('kind')] = kinds.get(command.get('kind'), 0) + 1
    intro = ('The %d commands of the editor at engine %s, by group: each with its description, its kind, the MCP toolsets '
             'that offer it, its parameters and their JSON Schema. Edit commands change the project, Query commands change '
             'nothing, Session commands change the editor\'s session.') % (len(commands), code(inputs.pin[:12]))
    toolset_rows = [[code(item['name']), md(item['description'])] for item in parsed['toolsets']['known']]
    toolsets = '## MCP toolsets\n\n' + table(['Toolset', 'What it holds'], toolset_rows)
    values = {'commands.count': len(commands), 'toolsets.count': len(parsed['toolsets']['known']),
              'toolsets.core.count': len(parsed['toolsets']['core'])}
    for kind, count in kinds.items():
        values['commands.%s.count' % str(kind).lower()] = count
    # reference/commands is one page (rulings 13, R59's approval) that includes the toolsets' file and one file per group,
    # with prose of its own before each group; past the largest page's budget the render fails instead of splitting it.
    files = {'commands-toolsets.md': finish(inputs.pin, [intro, toolsets])}
    for group, items in sorted(groups.items()):
        text = '\n\n'.join(command_section(command, registrations[command['name']], parsed['toolsets'], examples.get(command['name']), '##')
                           for command in items)
        group_intro = ('The %d %s commands of the editor at engine %s: each with its description, its kind, the MCP toolsets that offer '
                       'it, its parameters and their JSON Schema (the other groups have files of their own).') % (
            len(items), code(group), code(inputs.pin[:12]))
        files['commands-%s.md' % group.lower()] = finish(inputs.pin, [group_intro, text])
    page = page_estimate('\n\n'.join(files[name] for name in sorted(files)))
    if page > budget:
        raise RenderError("reference/commands would be a page of about %d KB, more than the largest page's budget of %d KB (tools/budgets.json): "
                          'the page stays one page (rulings 13, R59): ask the planner for a ruling on the budget' % (page // 1024, budget // 1024))
    return files, values


def render_debug_views(inputs):
    commands = {command['name']: command for command in inputs.dump('commands').get('commands') or []}
    capture = commands.get('viewport.capture')
    schema = ((capture or {}).get('parameters') or {}).get('properties', {}).get('debugView')
    if not isinstance(schema, dict) or not schema.get('enum'):
        raise RenderError('reference/_dumps/%s/commands.json: viewport.capture has no debugView enum: dump again, or change '
                          'tools/booklib/tables.py if the engine moved the debug views' % inputs.pin)
    intro = ('The debug views of %s at engine %s: the values of its %s parameter. %s') % (
        code('viewport.capture'), code(inputs.pin[:12]), code('debugView'), md(schema.get('description')))
    text = finish(inputs.pin, [intro, table(['Debug view'], [[code(value)] for value in schema['enum']])])
    return {'debug-views.md': text}, {'debugViews.count': len(schema['enum'])}


# ---------------------------------------------------------------------------------------------------------------------
# Components.

def property_range(item):
    parts = []
    if item.get('Options'):
        parts.append('One of: %s.' % ', '.join(code(option) for option in item['Options']))
    if 'Min' in item and 'Max' in item and not (item['Min'] == 0 and item['Max'] == 0):
        parts.append('%s to %s.' % (value_text(item['Min']), value_text(item['Max'])))
    if item.get('AssetType'):
        parts.append('Asset type: %s.' % code(item['AssetType']))
    if item.get('PhysicsLayer'):
        parts.append('A collision layer.')
    if item.get('ReadOnly'):
        parts.append('Read-only.')
    return ' '.join(parts)


def render_components(inputs):
    components = inputs.dump('components').get('components') or []
    defaults = {record['component']: record for record in inputs.dump('component-defaults').get('components') or []}
    parsed = inputs.route('components')
    inactive = {}
    for record in parsed['inactive']:
        inactive.setdefault((record['component'], record['property']), record)
    categories = {}
    for component in components:
        categories.setdefault(component.get('category') or 'Other', []).append(component)
    parts = [('The %d components of the engine at %s that %s lists, by category: each property with its type, its '
              'default (the value %s reports on a new entity), its range or options, and when it has no effect.') % (
        len(components), code(inputs.pin[:12]), code('component.list'), code('entity.get'))]
    for category in sorted(categories):
        section = ['## %s' % md(category)]
        for component in sorted(categories[category], key=lambda item: item['name']):
            name = component['name']
            section.append('### %s' % name)
            facts = ['Display name: %s' % md(component.get('displayName')), 'Added by people and tools: %s' % ('yes' if component.get('addable') else 'no'),
                     'Removable: %s' % ('yes' if component.get('removable') else 'no')]
            if component.get('description'):
                section.append(md(component['description']))
            section.append(' · '.join(facts))
            record = defaults.get(name)
            values = (record or {}).get('values') or {}
            if record and record.get('added'):
                section.append('Adding it also adds %s.' % ', '.join(code(item) for item in record['added']))
            if record and 'error' in record:
                section.append('It has no defaults here: %s refuses it on a new entity (%s).' % (code('component.add'), md(record['error'])))
            elif not component.get('addable'):
                section.append('It has no defaults here: people and tools do not add it.')
            rows = []
            for item in component.get('properties') or []:
                property_name = item['Name']
                reason = inactive.get((name, property_name))
                notes = [md(item.get('Description'))]
                if reason:
                    messages = '; '.join(md(message) for message in reason['messages']) or code(reason['function'])
                    notes.append('Inactive (it has no effect) when: %s' % messages)
                if item.get('Section'):
                    notes.append('Inspector section: %s' % md(item['Section']))
                rows.append([code(property_name), md(item.get('DisplayName')), code(item.get('Type')),
                             value_text(values[property_name]) if property_name in values else '', property_range(item), sentences(notes)])
            if rows:
                section.append(table(['Property', 'Display name', 'Type', 'Default', 'Range', 'Description'], rows))
            else:
                section.append('No properties.')
        parts.append('\n\n'.join(section))
    listed = {component['name'] for component in components}
    hidden = [record for record in parsed['components'] if record['name'] not in listed]
    if hidden:
        rows = []
        for record in hidden:
            rows.append([code(record['name']), ', '.join(code(flag) for flag in record['flags']) or '',
                         ', '.join(code(item['name']) for item in record['properties']) or '', md(record.get('description')),
                         where(record['file'], record['line'])])
        parts.append('## Components the list leaves out\n\n%s leaves out hidden components and those the scene stores itself '
                     '(NoSerialize). They are registered in the source:\n\n%s' % (
                         code('component.list'), table(['Component', 'Flags', 'Properties', 'Description', 'Registered at'], rows)))
    rows = []
    for record in parsed['components']:
        if record['name'] not in listed:
            continue
        for item in record['properties']:
            if set(item['flags']) & {'Hidden', 'Transient'}:
                rows.append([code(record['name']), code(item['name']), ', '.join(code(flag) for flag in item['flags']),
                             where(record['file'], item['line'])])
    if rows:
        parts.append('## Properties the list leaves out\n\nHidden properties are stored but not shown; transient ones are not '
                     'stored.\n\n%s' % table(['Component', 'Property', 'Flags', 'Registered at'], rows))
    values = {'components.count': len(components), 'components.addable.count': sum(1 for component in components if component.get('addable'))}
    return {'components.md': finish(inputs.pin, parts)}, values


# ---------------------------------------------------------------------------------------------------------------------
# Settings and preferences.

def field_rows(schema):
    rows = []
    properties = schema.get('properties') if isinstance(schema.get('properties'), dict) else {}
    for name, item in properties.items():
        item = item if isinstance(item, dict) else {}
        rows.append([code(name), md(item.get('title')), md(schema_type(item)), value_text(item.get('default')) if 'default' in item else '',
                     sentences([md(item.get('description')), schema_notes(item)])])
    return rows


def section_block(section, new_value=None):
    schema = section.get('schema') or {}
    lines = ['### %s' % section['id']]
    facts = ['Title: %s' % md(section.get('title')), 'Category: %s' % md(section.get('category')), 'Version: %s' % code(section.get('version'))]
    if section.get('description'):
        lines.append(md(section['description']))
    lines.append(' · '.join(facts))
    properties = schema.get('properties') if isinstance(schema.get('properties'), dict) else {}
    simple = properties and all(isinstance(item, dict) and 'default' in item for item in properties.values())
    rows = field_rows(schema)
    if rows:
        lines.append(table(['Field', 'Title', 'Type', 'Default', 'Description'], rows))
    if not simple:
        if new_value is not None:
            lines.append('Its schema gives no default per field; a new project holds this value:')
            lines.append(details('Default value of %s' % section['id'], new_value))
        else:
            lines.append('Its schema gives no default per field.')
    lines.append(details('Schema of %s' % section['id'], schema))
    return '\n\n'.join(lines)


def render_settings(inputs):
    result = inputs.dump('settings')
    sections = result.get('sections') or []
    parts = [('The %d project settings sections of the engine at %s, as %s describes a new empty project, in registration order. '
              'The defaults are the schemas\' (and, where a schema has none per field, the new project\'s value).') % (
        len(sections), code(inputs.pin[:12]), code('project.settings'))]
    for section in sections:
        parts.append(section_block(section, section.get('value') if section.get('isDefault') else None))
    files = {'settings.md': finish(inputs.pin, parts)}
    preferences = inputs.dump('preferences').get('sections') or []
    preference_parts = [('The %d preference sections of the editor at %s, as %s describes them: their schemas and defaults, never a '
                         'person\'s values.') % (len(preferences), code(inputs.pin[:12]), code('preferences.get'))]
    for section in preferences:
        preference_parts.append(section_block(section))
    files['preferences.md'] = finish(inputs.pin, preference_parts)
    return files, {'settings.count': len(sections), 'preferences.count': len(preferences)}


# ---------------------------------------------------------------------------------------------------------------------
# Asset types, budgets and statistics.

def render_asset_types(inputs):
    parsed = inputs.route('asset-types')
    rows = [[code(item['name']), code(item['value']), md(item['comment'])] for item in parsed['types']]
    importer_rows = [[code(item['type']), code(item['class']), code(item['version']), ', '.join(code(extension) for extension in item['extensions']),
                      where(item['file'], item['line'])] for item in parsed['importers']]
    parts = ['The asset types of the engine at %s (the %s enum of %s; the values are stored in packs and import records) and '
             'the importers with their versions: an importer\'s version changes whenever what it writes changes, which '
             'imports the assets again.' % (code(inputs.pin[:12]), code('AssetType'), code(parsed['file'])),
             '## Asset types\n\n' + table(['Type', 'Value', 'Note'], rows),
             '## Importers\n\n' + table(['Type', 'Importer', 'Version', 'Extensions', 'Defined at'], importer_rows)]
    values = {'assetTypes.count': sum(1 for item in parsed['types'] if item['name'] != 'None')}
    for item in parsed['importers']:
        values['importer.%s.version' % item['type']] = item['version']
    return {'asset-types.md': finish(inputs.pin, parts)}, values


def render_asset_budgets(inputs):
    sections = [section for section in inputs.dump('settings').get('sections') or [] if section['id'].startswith('Asset')
                or (section.get('category') or '') == 'Assets']
    commands = {command['name']: command for command in inputs.dump('commands').get('commands') or []}
    stats = commands.get('asset.stats')
    if stats is None:
        raise RenderError('reference/_dumps/%s/commands.json: no asset.stats command: dump again, or change tools/booklib/tables.py '
                          'if the engine renamed it' % inputs.pin)
    parts = ['The asset budgets and statistics of the engine at %s: the asset settings sections of a new project and what %s '
             'reports, as its description states it.' % (code(inputs.pin[:12]), code('asset.stats'))]
    if sections:
        parts += [section_block(section, section.get('value') if section.get('isDefault') else None) for section in sections]
    else:
        parts.append('A new project has no asset settings section: the budgets are set with %s and reported by %s.' % (
            code('asset.setBudget'), code('asset.stats')))
    budget = commands.get('asset.setBudget')
    parts.append('## asset.stats\n\n' + md(stats.get('description')))
    if budget:
        parts.append('## asset.setBudget\n\n' + md(budget.get('description')) + '\n\n' + table(
            ['Parameter', 'Type', 'Required', 'Default', 'Description'], parameter_rows(budget.get('parameters') or {})))
    return {'asset-budgets.md': finish(inputs.pin, parts)}, {}


# ---------------------------------------------------------------------------------------------------------------------
# Renderer: quality, GPU stages, statistics, specification.

def quality_value(value, field):
    """A row's value as the Renderer.Quality field writes it: an option of the field's enum where it has one."""
    options = field.get('enum') if isinstance(field, dict) else None
    if not options:
        return value
    if isinstance(value, (int, float)):
        text = str(int(value)) if float(value).is_integer() else str(value)
        if text in options:
            return text
        return None
    name = str(value).split('::')[-1]
    if name in options:
        return name
    matches = [option for option in options if name.endswith(option) and option not in ('Off',)]
    return matches[0] if len(matches) == 1 else None


def render_quality(inputs):
    parsed = inputs.route('quality')
    sections = {section['id']: section for section in inputs.dump('settings').get('sections') or []}
    section = sections.get('Renderer.Quality')
    if section is None:
        raise RenderError('reference/_dumps/%s/settings.json: no Renderer.Quality section: dump the settings again' % inputs.pin)
    fields = (section.get('schema') or {}).get('properties') or {}
    rows = []
    values = {}
    for item in parsed['rows']:
        field = fields.get(item['row'])
        if field is None:
            raise RenderError('%s:%d: the row c_%sRow has no field %s in the Renderer.Quality schema of settings.json: dump the settings '
                              'and parse again at one pin' % (parsed['file'], item['line'], item['row'], item['row']))
        shown = []
        for preset, value in zip(c_Presets, item['values']):
            written = quality_value(value, field)
            if written is None:
                raise RenderError('%s:%d: the %s value %s of c_%sRow is none of the field\'s options %s: change quality_value in '
                                  'tools/booklib/tables.py' % (parsed['file'], item['line'], preset, value, item['row'], field.get('enum')))
            shown.append(written)
            values['quality.%s.%s' % (item['row'], preset)] = written
        if 'default' in field and shown[2] != field['default']:
            raise RenderError('%s:%d: c_%sRow\'s High value %s is not the field\'s default %s, which the engine gives High\'s value: '
                              'change quality_value in tools/booklib/tables.py, or tell the planner the engine changed' % (
                                  parsed['file'], item['line'], item['row'], shown[2], field['default']))
        rows.append([code(item['row']), md(field.get('title'))] + [value_text(value) for value in shown] + [md(field.get('description'))])
    others = [[code(name), md(field.get('title')), value_text(field.get('default')), md(field.get('description'))]
              for name, field in fields.items() if name not in {item['row'] for item in parsed['rows']}]
    parts = ['The Graphics Quality presets of the engine at %s: each row of %s with its value in the four presets, as the %s '
             'settings section writes it (High is the default). Custom uses the values a project or a player sets.' % (
                 code(inputs.pin[:12]), code(parsed['file']), code('Renderer.Quality')),
             '## Rows\n\n' + table(['Field', 'Title'] + list(c_Presets) + ['Description'], rows)]
    if others:
        parts.append('## The section\'s other fields\n\nNo preset sets these; each has its default.\n\n' + table(
            ['Field', 'Title', 'Default', 'Description'], others))
    return {'quality.md': finish(inputs.pin, parts)}, values


def render_gpu_stages(inputs):
    parsed = inputs.route('gpu-stages')
    rows = [[code(item['name']), code(item['call']), where(item['file'], item['line'])] for item in parsed['stages']]
    text = finish(inputs.pin, ['The GPU stages of the frame profiler at engine %s: the names passed to %s and to %s with %s. '
                               'Each is a column of the runtime\'s perf log and a row of %s.' % (
                                   code(inputs.pin[:12]), code('RegisterGPUStage'), code('RegisterStage'), code('FrameStageKind::GPU'),
                                   code('editor.perf')),
                               table(['Stage', 'Registered by', 'Where'], rows)])
    return {'gpu-stages.md': text}, {'gpuStages.count': len(parsed['stages'])}


def render_cpu_stages(inputs):
    """The CPU's frame stages (pipelines.md §7.1, "CPU stages"; rulings-10.md, R48), beside the GPU's."""
    parsed = inputs.route('frame-stages')
    if 'cpu' not in parsed:
        raise RenderError('parsed/frame-stages.json has no "cpu": run python -I tools/reference.py parse --engine <clone>')
    rows = []
    for item in parsed['cpu']:
        declared = '; '.join('%s, %s' % (code(place['by']), where(place['file'], place['line'])) for place in item['declared'])
        timed = ', '.join(where(place['file'], place['line']) for place in item['timed'])
        rows.append([code(item['name']), declared, timed, 'yes' if item['inWorkTime'] else 'no'])
    text = finish(inputs.pin, ['The CPU stages of the frame profiler at engine %s: the built-in stages of %s, the names passed to %s and to '
                               '%s without %s, and the %s of each scene system\'s descriptor. Each is a column of the runtime\'s perf log '
                               'and a row of %s. A stage outside the work time is not counted in the frame\'s work time (%s).' % (
                                   code(inputs.pin[:12]), code('c_BuiltinFrameStages'), code('ST_PROFILE_STAGE'), code('RegisterStage'),
                                   code('FrameStageKind::GPU'), code('ProfileStage'), code('editor.perf'),
                                   code('Application::GetLastFrameWorkTime')),
                               table(['Stage', 'Declared by', 'Timed in', 'In the work time'], rows)])
    return {'cpu-stages.md': text}, {'cpuStages.count': len(parsed['cpu'])}


def stats_rows(keys, fields, prefix=''):
    rows = []
    for item in keys:
        name = prefix + item['key']
        comment = item.get('comment') or ''
        source = item.get('source')
        if not comment and source:
            comment = fields.get(source.split('::', 1)[1], {}).get('comment', '')
        rows.append([code(name), code(source) if source else '', md(comment)])
        if item.get('children'):
            rows += stats_rows(item['children'], fields, name + '.')
    return rows


def render_render_stats(inputs):
    parsed = inputs.route('render-stats')
    renderer = inputs.route('renderer')
    fields = {field['name']: field for field in renderer['stats']['fields']}
    rows = stats_rows(parsed['keys'], fields)
    text = finish(inputs.pin, ['The keys of %s, which %s and %s report for the viewport\'s latest frame, at engine %s (%s). '
                               'Where the source gives no comment of its own, the description is that of the %s field it reports.' % (
                                   code('renderStats'), code('viewport.capture'), code('editor.status'), code(inputs.pin[:12]),
                                   where(parsed['file'], parsed['line']), code('SceneRendererStats')),
                               table(['Key', 'From', 'Description'], rows)])
    return {'render-stats.md': text}, {'renderStats.count': len(parsed['keys'])}


def render_renderer(inputs):
    parsed = inputs.route('renderer')
    parts = ['The fields of the scene renderer\'s specification and statistics at engine %s (%s).' % (code(inputs.pin[:12]), code(parsed['file']))]
    for key, title in (('specification', 'SceneRendererSpecification'), ('stats', 'SceneRendererStats')):
        data = parsed[key]
        rows = [[code(field['name']), code(field['type']), value_text(field['default']) if field['default'] is not None else '', md(field['comment'])]
                for field in data['fields']]
        parts.append('## %s\n\nDeclared at %s.\n\n%s' % (title, where(parsed['file'], data['line']), table(['Field', 'Type', 'Default', 'Description'], rows)))
    return {'renderer.md': finish(inputs.pin, parts)}, {}


def render_perf_log(inputs):
    parsed = inputs.route('perf-log')
    rows = []
    for column in parsed['columns']:
        name = '<stage>…' if column['name'] == '<stage>' else column['name']
        description = column['description']
        rows.append([code(name), sentences([md(description[:1].upper() + description[1:])])])
    for group in parsed['groups']:
        for name in group['names']:
            rows.append([code(name), 'A column of the runtime\'s group %s (%s), empty in a row whose frame was not captured.' % (
                code(group['owner'] + '::MakePerfLogColumns'), where(group['file'], group['line']))])
    text = finish(inputs.pin, ['The columns of the runtime\'s perf log (%s), in the order the file writes them, at engine %s '
                               '(%s). %s stands for one column per stage the frame profiler registered, in milliseconds.' % (
                                   code('StrataRuntime --perf-log'), code(inputs.pin[:12]), code(parsed['file']), code('<stage>…')),
                               table(['Column', 'Description'], rows)])
    return {'perf-log.md': text}, {}


