# Program options.

def render_options(inputs):
    parsed = inputs.route('options')
    details_data = parsed['details']
    files = {}
    for program, name in (('StrataEditor', 'options-editor.md'), ('StrataRuntime', 'options-runtime.md')):
        data = details_data[program]
        rows = [[code(item['option']), code(item['value']) if item['value'] else '', md(item['description'])] for item in data['options']]
        files[name] = finish(inputs.pin, ['The command-line options of %s at engine %s (%s, %s).' % (
            code(program), code(inputs.pin[:12]), code('c_Arguments'), code(data['file'])), table(['Option', 'Value', 'What it does'], rows)])
    cli = details_data['StrataCLI']
    parts = ['The commands and options of %s at engine %s, from its usage text (%s).' % (code('StrataCLI'), code(inputs.pin[:12]), where(cli['file'], cli['line'])),
             '## Usage\n\n' + '\n'.join('- %s' % code(line) for line in cli['usage']),
             '## Commands\n\n' + table(['Command', 'What it does'], [[code(item['name']), md(item['description'])] for item in cli['commands']]),
             '## Connection options\n\n' + table(['Option', 'Meaning'], [[code(item['name']), md(item['description'])] for item in cli['connection']])
             + ('\n\n' + ' '.join(md(note) for note in cli['connectionNotes']) if cli['connectionNotes'] else ''),
             '## Other options\n\n' + table(['Option', 'Meaning'], [[code(item['name']), md(item['description'])] for item in cli['other']]),
             '## Environment\n\n' + table(['Variable', 'Meaning'], [[code(item['name']), md(item['description'])] for item in cli['environment']]),
             '## Exit codes\n\n' + md(cli['exitCodes'])]
    files['options-cli.md'] = finish(inputs.pin, parts)
    return files, {}


# ---------------------------------------------------------------------------------------------------------------------
# Script API.

def render_script_api(inputs):
    parsed = inputs.route('script-api')
    host = parsed['hostAPI']
    classes = parsed['classDesc']
    functions = [member for member in host['members'] if member['kind'] == 'function']
    callbacks = [member for member in classes['members'] if member['kind'] == 'function']
    parts = ['The script API at engine %s: the host functions of %s in their order (the ABI appends, so the order is that of '
             'the releases), the callbacks of %s, and the SDK\'s public classes, functions and macros, which scripts are written '
             'against. "Added in" is the first engine release that has the function.' % (
                 code(inputs.pin[:12]), code('StrataScriptHostAPI'), code('StrataScriptClassDesc'))]
    rows = [[str(number), code(member['name']), code(member['declaration']), member['addedIn'], md(member['comment'])]
            for number, member in enumerate(functions, 1)]
    parts.append('## Host functions\n\n%s (%s) holds them. The engine\'s list of them is %s in %s, not the SDK\'s.\n\n%s' % (
        code('StrataScriptHostAPI'), where(parsed['file'], host['line']), code('ST_SCRIPT_HOST_FUNCTIONS'),
        code('Strata/src/Strata/Scripting/ScriptHostAPI.cpp'), table(['#', 'Function', 'Declaration', 'Added in', 'Description'], rows)))
    rows = [[code(member['name']), code(member['declaration']), member.get('addedIn', ''), md(member['comment'])] for member in classes['members']]
    parts.append('## Script class callbacks\n\n%s (%s).\n\n%s' % (code('StrataScriptClassDesc'), where(parsed['file'], classes['line']),
                                                                 table(['Member', 'Declaration', 'Added in', 'Description'], rows)))
    sdk = parsed['sdk']
    by_owner = {}
    for function in sdk['functions']:
        owner = function['class'] or (function['namespace'] or '(Strata)')
        by_owner.setdefault((0 if function['class'] else 1, owner), []).append(function)
    for (kind, owner), items in sorted(by_owner.items()):
        title = 'Class %s' % owner if kind == 0 else ('Namespace %s' % owner if owner != '(Strata)' else 'Free functions of Strata')
        rows = [[code(function['name']), code(function['declaration']), md(function['comment']), where(function['file'], function['line'])]
                for function in items]
        parts.append('## %s\n\n%s' % (title, table(['Function', 'Declaration', 'Comment', 'Declared at'], rows)))
    rows = [[code(macro['name'] + ('(%s)' % macro['parameters'] if macro['parameters'] else '')), md(macro['comment']), where(macro['file'], macro['line'])]
            for macro in sdk['macros']]
    parts.append('## Macros\n\n' + table(['Macro', 'Comment', 'Defined at'], rows))
    values = {'hostFunctions.count': len(functions), 'scriptCallbacks.count': len(callbacks),
              'sdkClasses.count': len({function['class'] for function in sdk['functions'] if function['class']})}
    return {'script-api.md': finish(inputs.pin, parts)}, values


# ---------------------------------------------------------------------------------------------------------------------
# Performance, limits, build.

def render_performance(inputs):
    parsed = inputs.route('performance')
    rows = []
    for entry in parsed['budgets']:
        rows.append([code(entry['name']), value_text(entry.get('Measured')), value_text(entry.get('Budget')), code(entry.get('Unit', '')),
                     value_text(entry.get('Target')) if 'Target' in entry else ''])
    comment = ' '.join(line.strip() for line in parsed['comment'] if isinstance(line, str))
    text = finish(inputs.pin, ['Every perf budget of the engine at %s (%s): what each metric measured on the reference machine '
                               'and the budget its test enforces. The file says:' % (code(inputs.pin[:12]), code(parsed['file'])),
                               '> ' + md(comment) if comment else '',
                               table(['Metric', 'Measured', 'Budget', 'Unit', 'Target'], rows)])
    # pipelines.md §7.3: each budget gives perf.<name>.<Measured|Budget|Unit>; a Provisional entry has no budget and gives
    # no key, so that no page states a number the reference machine has not measured.
    values = {'perfBudgets.count': len(parsed['budgets'])}
    for entry in parsed['budgets']:
        if entry.get('Provisional'):
            continue
        for field in ('Measured', 'Budget', 'Unit'):
            if field in entry:
                values['perf.%s.%s' % (entry['name'], field)] = entry[field]
    return {'performance.md': text}, values


def render_limits(inputs):
    parsed = inputs.route('limits')
    rows = [[code(item['name']), value_text(item['value']), code(item['expression']), md(item['comment']), where(item['file'], item['line'])]
            for item in parsed['limits']]
    values = {item['key']: item['value'] for item in parsed['limits']}
    text = finish(inputs.pin, ['The limits of scenes and worlds at engine %s: each constant, its value and the expression the source '
                               'writes it with.' % code(inputs.pin[:12]), table(['Constant', 'Value', 'Written as', 'Comment', 'Declared at'], rows)])
    return {'limits.md': text}, values


def render_build(inputs):
    parsed = inputs.route('build')
    parts = ['The build of the engine at %s: its CMake options, its presets, its CTest tests with their labels and how the '
             'unit tests are split into shards.' % code(inputs.pin[:12])]
    parts.append('## CMake options\n\n' + table(['Option', 'Default', 'Description', 'Defined at'], [
        [code(item['name']), code(item['default']), md(item['description']), where(item['file'], item['line'])] for item in parsed['options']]))
    presets = parsed['presets']
    parts.append('## Configure presets\n\n' + table(['Preset', 'Display name', 'Generator', 'Build folder', 'Description'], [
        [code(item['name']), md(item.get('displayName')), md(item.get('generator')), code(item['binaryDir']) if item.get('binaryDir') else '',
         md(item.get('description')) + (' Hidden (a base of others).' if item.get('hidden') else '')] for item in presets['configurePresets']]))
    if presets['buildPresets']:
        parts.append('## Build presets\n\n' + table(['Preset', 'Configure preset', 'Configuration'], [
            [code(item['name']), code(item.get('configurePreset', '')), code(item.get('configuration', ''))] for item in presets['buildPresets']]))
    if presets['testPresets']:
        parts.append('## Test presets\n\n' + table(['Preset', 'Configure preset', 'Configuration', 'Filter'], [
            [code(item['name']), code(item.get('configurePreset', '')), code(item.get('configuration', '')),
             value_text(item.get('filter')) if item.get('filter') else ''] for item in presets['testPresets']]))
    parts.append('## CTest tests\n\n' + table(['Test', 'Labels'], [
        [code(item['name']), ', '.join(code(label) for label in item['labels'])] for item in parsed['tests']]))
    shards = parsed['shards']
    if shards.get('Description'):
        parts.append('## Shards\n\n' + md(shards['Description']))
    else:
        parts.append('## Shards')
    parts.append(table(['CTest', 'Suites', 'Excluded'], [
        [code(item['Test']), ', '.join(code(suite) for suite in item.get('Suites', [])), ', '.join(code(suite) for suite in item.get('Exclude', []))]
        for item in shards.get('OwnTests', [])] + [
        [code('StrataTests.Core.' + item['Name']), ', '.join(code(suite) for suite in item.get('Suites', [])),
         ', '.join(code(suite) for suite in item.get('Exclude', []))] for item in shards.get('Shards', [])]))
    tests = inputs.route('tests')
    values = {'cmakeOptions.count': len(parsed['options']), 'ctest.count': len(parsed['tests']), 'doctestSuites.count': len(tests['suites'])}
    return {'build.md': finish(inputs.pin, parts)}, values


# ---------------------------------------------------------------------------------------------------------------------
# Figures.

def render_figures(inputs, layout):
    rows = []
    count = 0
    for path in sorted(glob.glob(os.path.join(layout.figures, '*', '*.json'))):
        page = os.path.relpath(path, layout.figures).replace(os.sep, '/')[:-5]
        try:
            with open(path, encoding='utf-8') as file:
                manifest = json.load(file)
        except ValueError as error:
            raise RenderError('%s: not valid JSON (%s): run python -I tools/figures.py check' % (layout.relative(path), error))
        taken = {}
        taken_path = os.path.join(layout.pictures, *page.split('/'), 'taken.json')
        if os.path.isfile(taken_path):
            try:
                with open(taken_path, encoding='utf-8') as file:
                    taken = (json.load(file) or {}).get('files') or {}
            except ValueError as error:
                raise RenderError('%s: not valid JSON (%s): run python -I tools/figures.py publish again' % (layout.relative(taken_path), error))
        for entry in manifest.get('figures') or []:
            if not isinstance(entry, dict) or 'id' not in entry:
                continue
            count += 1
            records = [record for record in taken.values() if isinstance(record, dict) and record.get('figure') == entry['id']]
            gpus = sorted({record.get('gpu') for record in records if record.get('gpu')})
            state = 'taken at %s' % ', '.join(sorted({code(record['pin'][:12]) for record in records if record.get('pin')})) if records else 'not taken yet'
            recipe = []
            for key in ('kind', 'project', 'scene', 'shot', 'camera', 'quality', 'debugView'):
                if key in entry:
                    recipe.append('%s %s' % (key, value_text(entry[key])))
            rows.append([code(page), code(entry['id']), md(entry.get('shows') or entry.get('caption')), '; '.join(recipe), state,
                         ', '.join(md(gpu) for gpu in gpus) if gpus else ''])
    text = finish(inputs.pin, ['Every figure of the book with what it shows, its recipe (the figure manifest of its page) and the '
                               'GPU of the machine that rendered it (its taken.json). A figure not taken yet has no GPU.',
                               table(['Page', 'Figure', 'What it shows', 'Recipe', 'State', 'GPU'], rows) if rows else 'No page has a figure yet.'])
    return {'figures.md': text}, {'figures.count': count}


# ---------------------------------------------------------------------------------------------------------------------

def render_all(folder, pin, examples, layout, budgets_path):
    """({file name: text}, problems) of every table and values.json."""
    try:
        inputs = Inputs(folder, pin)
        example_results = read_examples(examples) if os.path.isdir(examples) else {}
        files = {}
        values = {'engine.commit': pin}
        renderers = [
            lambda: render_commands(inputs, example_results, page_budget(budgets_path)),
            lambda: render_debug_views(inputs),
            lambda: render_components(inputs),
            lambda: render_settings(inputs),
            lambda: render_asset_types(inputs),
            lambda: render_asset_budgets(inputs),
            lambda: render_quality(inputs),
            lambda: render_gpu_stages(inputs),
            lambda: render_cpu_stages(inputs),
            lambda: render_render_stats(inputs),
            lambda: render_renderer(inputs),
            lambda: render_perf_log(inputs),
            lambda: render_options(inputs),
            lambda: render_script_api(inputs),
            lambda: render_performance(inputs),
            lambda: render_limits(inputs),
            lambda: render_build(inputs),
            lambda: render_figures(inputs, layout),
        ]
        problems = []
        for renderer in renderers:
            try:
                made, keys = renderer()
            except RenderError as error:
                problems.append(str(error))
                continue
            files.update(made)
            for key, value in keys.items():
                if key in values:
                    problems.append('tools/booklib/tables.py: two tables write the key %s of values.json: give one of them another name' % key)
                values[key] = value
        values['samples.count'] = len(inputs.dump('samples').get('samples') or [])
        values['templates.count'] = len(inputs.dump('templates').get('templates') or [])
    except RenderError as error:
        return {}, [str(error)]
    if problems:
        return {}, problems
    files['values.json'] = json.dumps(dict(sorted(values.items())), indent='\t', ensure_ascii=False) + '\n'
    return files, []

